package com.pratik.imagetap;
import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import java.util.*;
public class FreshRecheckTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static Mat screen(Mat target,int x,int y){Mat s=new Mat(1280,720,CvType.CV_8UC4,new Scalar(20,25,35,255));Mat patch=s.submat(y,y+target.rows(),x,x+target.cols());target.copyTo(patch);patch.release();return s;}
 public static void main(String[]args){nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);Mat target=new Mat(48,72,CvType.CV_8UC4,new Scalar(45,60,90,255));Imgproc.putText(target,"EXIT",new Point(2,34),Imgproc.FONT_HERSHEY_SIMPLEX,.65,new Scalar(245,230,220,255),2);VisionMatcher.Hit old=new VisionMatcher.Hit(300,400,72,48,99,96);
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,300,400),720,96,Collections.emptyList())){VisionMatcher.Hit h=VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE);check(h!=null&&h.x==300&&h.y==400,"Stationary target must verify on identical new screenshot");}
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,307,405),720,96,Collections.emptyList())){VisionMatcher.Hit h=VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE);check(h!=null&&h.x==307&&h.y==405,"Small movement updates action position");}
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,550,700),720,96,Collections.emptyList())){check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)==null,"Disappeared target cannot dispatch at old location");}
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,300,400),720,96,Arrays.asList(new RegionRules.Region(.4f,.3f,.6f,.4f,100,true)))){check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)==null,"Excluded area still respected");}
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,300,400),720,100,Collections.emptyList())){check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)!=null,"Exact pixels pass 100%");check(VisionMatcher.recheck(f,target,old,new RegionRules.Region(0,0,.2f,.2f,96),Long.MAX_VALUE)==null,"Target area respected");check(VisionMatcher.recheck(f,target,old,null,0)==null,"Expired work blocked");f.cancelled=()->true;check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)==null,"Cancelled work blocked");}
 Mat changed=screen(target,300,400);changed.put(410,310,new byte[]{1,2,3,(byte)255});try(VisionMatcher.Frame f=new VisionMatcher.Frame(changed,720,100,Collections.emptyList())){check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)==null,"100% rejects changed pixels");}
 Mat cross=new Mat(24,24,CvType.CV_8UC4,new Scalar(0,0,0,0));Imgproc.line(cross,new Point(4,4),new Point(19,19),new Scalar(255,255,255,255),3);Imgproc.line(cross,new Point(19,4),new Point(4,19),new Scalar(255,255,255,255),3);
 Mat bg=new Mat(400,300,CvType.CV_8UC4,new Scalar(25,45,65,255));Mat dst=bg.submat(150,174,120,144),mask=new Mat();Core.extractChannel(cross,mask,3);cross.copyTo(dst,mask);dst.release();mask.release();try(VisionMatcher.Frame f=new VisionMatcher.Frame(bg,300,90,Collections.emptyList())){check(VisionMatcher.recheck(f,cross,new VisionMatcher.Hit(120,150,24,24,98,90),null,Long.MAX_VALUE)!=null,"Masked icon verifies without saved background");}cross.release();
 try(VisionMatcher.Frame f=new VisionMatcher.Frame(screen(target,300,400),720,96,Collections.emptyList())){long start=System.nanoTime();for(int i=0;i<51;i++)check(VisionMatcher.recheck(f,target,old,null,Long.MAX_VALUE)!=null,"All candidates verified");System.out.println("51 local verifications desktop ms="+(System.nanoTime()-start)/1000000);}
 target.release();System.out.println("PASS fresh recheck: static, moved, missing, excluded, exact, altered, target region, expiry and cancellation");
 }
}
